package dev.zyon;
import java.nio.FloatBuffer;
import java.lang.reflect.Field;
import net.minecraft.client.renderer.GlStateManager;
import net.minecraft.client.renderer.OpenGlHelper;
import org.lwjgl.BufferUtils;
import org.lwjgl.opengl.*;

/** Separate, real OpenGL verification; not run by the headless unit-test task. */
public final class HudRenderStateGlCheck {
 private static void check(boolean condition,String message){if(!condition)throw new AssertionError(message);}
 private static String snapshot(){StringBuilder s=new StringBuilder();for(int p:new int[]{GL11.GL_ALPHA_TEST,GL11.GL_DEPTH_TEST,GL11.GL_BLEND,GL11.GL_LIGHTING,GL11.GL_COLOR_MATERIAL,GL11.GL_CULL_FACE,GL11.GL_NORMALIZE,32826})s.append(GL11.glIsEnabled(p)).append('/');for(int p:new int[]{GL11.GL_ALPHA_TEST_FUNC,GL11.GL_DEPTH_FUNC,GL14.GL_BLEND_SRC_RGB,GL14.GL_BLEND_DST_RGB,GL14.GL_BLEND_SRC_ALPHA,GL14.GL_BLEND_DST_ALPHA,GL11.GL_SHADE_MODEL,GL11.GL_MATRIX_MODE,GL11.GL_ATTRIB_STACK_DEPTH,GL11.GL_MODELVIEW_STACK_DEPTH,GL11.GL_PROJECTION_STACK_DEPTH})s.append(GL11.glGetInteger(p)).append('/');s.append(GL11.glGetBoolean(GL11.GL_DEPTH_WRITEMASK)).append('/').append(GL11.glGetFloat(GL11.GL_ALPHA_TEST_REF));for(int p:new int[]{GL11.GL_CURRENT_COLOR,GL11.GL_COLOR_CLEAR_VALUE,GL11.GL_MODELVIEW_MATRIX,GL11.GL_PROJECTION_MATRIX}){FloatBuffer b=BufferUtils.createFloatBuffer(16);GL11.glGetFloat(p,b);for(int i=0;i<(p==GL11.GL_CURRENT_COLOR||p==GL11.GL_COLOR_CLEAR_VALUE?4:16);i++)s.append('/').append(Float.floatToIntBits(b.get(i)));}int active=GL11.glGetInteger(GL13.GL_ACTIVE_TEXTURE);s.append('/').append(active);for(int i=0;i<2;i++){GlStateManager.setActiveTexture(GL13.GL_TEXTURE0+i);s.append('/').append(GL11.glGetInteger(GL11.GL_TEXTURE_BINDING_2D)).append('/').append(GL11.glIsEnabled(GL11.GL_TEXTURE_2D));FloatBuffer b=BufferUtils.createFloatBuffer(16);GL11.glGetFloat(GL11.GL_TEXTURE_MATRIX,b);for(int j=0;j<16;j++)s.append('/').append(Float.floatToIntBits(b.get(j)));}GlStateManager.setActiveTexture(active);return s.toString();}
 public static void main(String[] args)throws Exception{
  Display.setDisplayMode(new DisplayMode(96,96));Display.create();try{OpenGlHelper.defaultTexUnit=GL13.GL_TEXTURE0;OpenGlHelper.lightmapTexUnit=GL13.GL_TEXTURE1;Field gl14=OpenGlHelper.class.getDeclaredField("openGL14");gl14.setAccessible(true);gl14.setBoolean(null,true);
   int first=GL11.glGenTextures(),second=GL11.glGenTextures(),changed=GL11.glGenTextures();GlStateManager.setActiveTexture(GL13.GL_TEXTURE0);GlStateManager.bindTexture(first);GlStateManager.enableTexture2D();GlStateManager.setActiveTexture(GL13.GL_TEXTURE1);GlStateManager.bindTexture(second);GlStateManager.disableTexture2D();GlStateManager.setActiveTexture(GL13.GL_TEXTURE0);GlStateManager.matrixMode(GL11.GL_MODELVIEW);GlStateManager.loadIdentity();GlStateManager.translate(1,2,3);GlStateManager.enableAlpha();GlStateManager.alphaFunc(GL11.GL_GREATER,.25f);GlStateManager.disableDepth();GlStateManager.depthMask(false);GlStateManager.enableBlend();GlStateManager.tryBlendFuncSeparate(770,771,1,0);GlStateManager.color(.8f,.9f,1,.75f);GlStateManager.shadeModel(GL11.GL_FLAT);
   String before=snapshot();for(int n=0;n<200;n++){try(HudRenderState state=new HudRenderState()){GlStateManager.disableAlpha();GlStateManager.enableDepth();GlStateManager.depthMask(true);GlStateManager.depthFunc(GL11.GL_EQUAL);GlStateManager.enableLighting();GlStateManager.enableLight(0);GlStateManager.enableColorMaterial();GlStateManager.colorMaterial(GL11.GL_FRONT,GL11.GL_DIFFUSE);GlStateManager.enableRescaleNormal();GlStateManager.color(.5f,.2f,.8f,1);GlStateManager.shadeModel(GL11.GL_SMOOTH);GlStateManager.tryBlendFuncSeparate(1,1,1,1);GlStateManager.clearColor(.1f,.2f,.3f,.4f);GlStateManager.colorMask(false,true,false,true);GlStateManager.setActiveTexture(GL13.GL_TEXTURE0);GlStateManager.bindTexture(changed);GlStateManager.matrixMode(GL11.GL_TEXTURE);GlStateManager.scale(8,8,8);GlStateManager.matrixMode(GL11.GL_MODELVIEW);GlStateManager.rotate(50,1,0,0);}check(before.equals(snapshot()),"Render state or matrix stack leaked after scope "+n);}
   GlStateManager.disableAlpha();check(!GL11.glIsEnabled(GL11.GL_ALPHA_TEST),"Alpha cache did not match OpenGL");GlStateManager.enableDepth();check(GL11.glIsEnabled(GL11.GL_DEPTH_TEST),"Depth cache did not match OpenGL");GlStateManager.bindTexture(changed);check(GL11.glGetInteger(GL11.GL_TEXTURE_BINDING_2D)==changed,"Texture cache did not match OpenGL");check(GL11.glGetError()==GL11.GL_NO_ERROR,"OpenGL reported an error");System.out.println("PASS: 200 render scopes restored matrices, transparency, depth, blending, lighting, colors, textures and Minecraft caches.");
  }finally{Display.destroy();}
 }
}
